import { FiBarChart2, FiPieChart, FiTrendingUp } from 'react-icons/fi';
import SectionTitle from './SectionTitle';
export default function About({ t }) { return <section id="about" className="section"><div className="container"><SectionTitle eyebrow="About" title={t.sections.about} subtitle={t.sections.aboutSub}/><div className="about-grid"><div className="about-text reveal"><h3>{t.about.title}</h3><p>{t.about.text}</p><div className="stats">{t.about.stats.map(s=><div className="stat" key={s[1]}><strong>{s[0]}</strong><span>{s[1]}</span></div>)}</div></div><div className="about-visual reveal" role="img" aria-label="Business accounting dashboard placeholder"><FiBarChart2/><FiPieChart/><FiTrendingUp/><div className="visual-card"><strong>Audit Ready</strong><span>Reports and documentation</span></div></div></div></div></section>; }
